from scipy.optimize import curve_fit
forms={
 'log+lin': (lambda X,a,b,c,d: a*np.log(1+b*X[0])+c*X[0]+d*X[1], [5,1,1,0.1]),
 'voce_pow_lin_pow': (lambda X,a,Q,b,m,k,p: a+Q*(1-np.exp(-b*X[0]**m))+k*X[0]**p, [-0.3,7,0.8,0.9,2.5,0.8]),
 'sat_exp2': (lambda X,a,Q,b,m,k,p: a+Q*(1-np.exp(-b*X[0]))+k*(1-np.exp(-m*X[0]**p)), [0,8,0.8,1,1.5,1]),
 'sqrt_sat': (lambda X,a,Q,b,k,c: a*np.sqrt(X[0])+Q*(1-np.exp(-b*X[0]))+k*X[0]+c*X[1], [1,8,0.8,1.5,0]),
}
for nm,(fn,p0) in forms.items():
    try:
        p,_=curve_fit(fn,(eps,T),sigma,p0=p0,maxfev=100000)
        r=sigma-fn((eps,T),*p)
        print(nm,p,np.var(r)/np.var(sigma))
    except Exception as ex: print(nm,ex)
